import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId, parseDate, fetchPostH, getUrlServerSide, compareJSON, fetchEncryptStream, qryStore, ObjectKeys } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt, CheckBox_Cmpt, DropDwnPicker_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { AddBusiness_Cmpt } from "..";
import { CodeVerifyView_Cmpt } from "../../Comprobantes";
import { OpenToast } from "../../../components/Toast";

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const TextInput = TextInput_Cmpt();

const DropDwnPicker = DropDwnPicker_Cmpt();


const CodeVerifyView = CodeVerifyView_Cmpt();


const AddBusiness = AddBusiness_Cmpt();



const frmNm = "upd_user"

const UpdUser  = ({data, confirm}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			getYearAccBussines(getStore(frmNm)?.businessId);
			set_obs(gen16CodeId())

			if(!getStore(frmNm)?.accessActivities){
				updFrm("accessActivities", accessActivities);
			}

			if(!getStore(frmNm)?.accessLogistic){
				updFrm("accessLogistic", accessLogistiFunc);
			}

		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};

	let flds = [
		"businessId",
		"isOwner",
		"role",
		"phoneNumber",
		"isqvmAgent",
		"telegram_chat_id",
		"isDelivery",
		"allowInventory",
		"phoneNumber",
		"state","city",
		"active",
		"accessActivities",
		"serviceState", 
		"serviceCity",
		"hasNotaryAccess",
		"hasSuperUserAccess",
		"hasLogisticAccess",
		"A2FA", "imageSSG", 
		"accessLogistic",
		"taxAuth", "notaryCasesAuth",
		"grabberId"
	]

	
	const save  = async ()  => {
		let ffm = getStore(frmNm);
		let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )

		
		let qqq = {...diff.data}
		/**
		qqq["state"] = "Holguin"
		qqq["serviceState"] = "Holguin"
		qqq["serviceCity"] = "80100"
		qqq["city"] = "80100"
		*/
		
		let bdyq2 = {
			query: "updateUserDetails",
			params:{
				"userId": ffm["userId"],
				
			},
			data2update: qqq
		};
		//Log$$(bdyq2)
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			updStore(frmNm + "_bck", {});
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
	};



	let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )

	
	const updObs = (f) => {
		set_obs(gen16CodeId())
	}

	const clean = (f) => {
		updStore("upd_user", data);
		updStore("upd_user_bck", JSON.parse(JSON.stringify(data)));
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		modaldata["content"] = <AddBusiness confirm={updObs} />
		
		OpenModal(modaldata);
	}

	const updGrabb = (f) => {
		set_obs(gen16CodeId())
	}

	

	const OpenYearAccountable = async (v) => {
		
		let bdyq2 = {...getStore(qryStore())?.upd_hrm_years};
		bdyq2.params = {
			businessId:  getStore(frmNm)?.businessId,
			businessYearId: getStore("businessYearId"),
		};
		bdyq2.data2update = {yearStatus:2};
		
		
		/* */
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		
		if (td && !td.error) {
			OpenToast({ text: "Done", timeout: 1500 });
			
		}
		
    }
	

	const requestCode =  async () => {
		
		let bdyq2 = {...getStore(qryStore())?.ask_notf_code};
		let tk = gen16CodeId()
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			phoneNumber: getStore("profileUser")?.phoneNumber,
			log: tk
		};
		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		
		if (td && !td.error) {
		
			let modaldata = {};
			modaldata["zIndex"] = 480;
			modaldata["height"] = "40vh";
			modaldata["content"] = <CodeVerifyView 
				info={td} tmk={tk}
				confirm={OpenYearAccountable}
			/>
			OpenModal(modaldata);
		}
	}



	const handleYear =  (y) => {
		updStore("date_current_year",y);
		if(getStore("YearAccBussinesUsr")?.[y]?.businessYearId){
			updStore("businessYearId",getStore("YearAccBussinesUsr")?.[y]?.businessYearId);
		}
		set_obs(gen16CodeId())
	}


	const updActivity =  (kA, v) => {
		let accessActivities = getStore(frmNm)["accessActivities"];
		accessActivities[kA] = v;
		updFrm("accessActivities",accessActivities);
	}

	const updActivityLog =  (kA, v) => {
		let accessLogistic = getStore(frmNm)["accessLogistic"];
		accessLogistic[kA] = v;
		updFrm("accessLogistic",accessLogistic);
	}

	

	console.log( getStore(frmNm))

	return (
		<div
		style={{
			maxHeight: "80vh",
			width: "960px",
			overflow: "auto",
			background: "#fff",
			borderRadius: 13,
			padding: "10px 19px"
		}}
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Actualizar Usuario
				</p>
				<div className="flexSpace"/>
				<p className="group_title addBtn" onClick={clean}>
					Add Business
				</p>
			</div>

			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<div className="_dsplFlx " style={{padding: "18px"}}>
					<div className="flexSpace"/>

					<DropDwnPicker 
						init={getStore(frmNm)?.["businessId"]}
						lbl_empty={"Business Name"} 
						list={getStore("bussines_list")} 
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						onSelect={(e)=>updFrm("businessId",e.id)}
					/>
					<div className="flexSpace"/>
				</div>
				<div className="_dsplFlx " style={{padding: "18px"}}>
					<div className="flexSpace"/>
					<DropDwnPicker 
						init={getStore(frmNm)?.["role"]}
						lbl_empty={"Roles"} 
						list={[
							{label: "Owner", id:"owner"},
							{label: "Lectura y Escritura", id:"write_read"},
							{label: "Solo Lectura", id:"read_only"},
						]} 
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						onSelect={(e)=>updFrm("role",e.id)}
						direction={"right"}
					/>
					<div className="flexSpace"/>
				</div>
			</div>
			
			<div className="_dsplFlx spaceAround"  style={{padding: "20px 3px 30px"}}>
				<DropDwnPicker 
					init={getStore("date_current_year")}
					lbl_empty={"Location"} 
					list={[
						{id:2022,label:2022},
						{id:2023,label:2023},
						{id:2024,label:2024}
					]} 
					onSelect={(e)=>handleYear(e.id)}
					background={"#f9f9f9"}
					color={"var(--hrm_palette-blue-purple)"}
					direction={"left"}
					width={"220px"}
				/>
				
				<div className="centerBx"> 
				{getStore(frmNm)?.businessId && getStore("businessYearId")? 
					<p style={{margin: "0 8px"}} className="group_title addBtn purple centerBx" onClick={requestCode}>
						Open Year
					</p>
					:null}
				</div>
			</div>


			<div className="_dsplFlx acc_dtls">
				<div className=""  >
					<div className="code" >
						{getStore(frmNm)?.["name"]} 
					</div>
					<div className="name" style={{marginTop: 9}}>
						{getStore(frmNm)?.["email"]}
					</div>
				</div>
			</div>

			<div className="_dsplFlx " style={{padding: "18px"}}>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["grabberId"]} 
					label={"Grabber Id"} 
					width={360} 
					updChanges={(e)=>updFrm("grabberId",e)}
				/>
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx " style={{padding: " 0 18px"}}>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["phoneNumber"]} 
					label={"phone Number"} 
					width={170} 
					type={"number"}
					updChanges={(e)=>updFrm("phoneNumber",e)}
				/>
				<div className="flexSpace"/>
				
			</div>

			<div className="_dsplFlx " style={{marginTop:35}}>
				<span className={`checklabel`}>
					{"Qvamarket Agente"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["isqvmAgent"]}
					keyCode={77}
					updChange={(e)=>updFrm("isqvmAgent",e)}
				/>
				<span className={`checklabel`}>
				
				</span>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Qvamarket Inventario"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["allowInventory"]}
					keyCode={79}
					updChange={(e)=>updFrm("allowInventory",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Agente Activo"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["active"]}
					keyCode={73}
					updChange={(e)=>updFrm("active",e)}
				/>
			</div>
			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Acceso a Notaria"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["hasNotaryAccess"]}
					keyCode={36}
					updChange={(e)=>updFrm("hasNotaryAccess",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Supervisor"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["hasSuperUserAccess"]}
					keyCode={36}
					updChange={(e)=>updFrm("hasSuperUserAccess",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Logistic Service"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["hasLogisticAccess"]}
					keyCode={56}
					updChange={(e)=>updFrm("hasLogisticAccess",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"2FA"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["A2FA"]}
					keyCode={73}
					updChange={(e)=>updFrm("A2FA",e)}
				/>
			</div>


			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Image SSG"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["imageSSG"]}
					keyCode={73}
					updChange={(e)=>updFrm("imageSSG",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Tax Auth"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["taxAuth"]}
					keyCode={73}
					updChange={(e)=>updFrm("taxAuth",e)}
				/>
			</div>

			<div className="_dsplFlx ">
				<span className={`checklabel`}>
					{"Notary Cases Auth"}
				</span>
				<CheckBoxSlide
					initvalue={getStore(frmNm)?.["notaryCasesAuth"]}
					keyCode={73}
					updChange={(e)=>updFrm("notaryCasesAuth",e)}
				/>
			</div>
			

			<div className="bxupdAct">
				{accessActivities && ObjectKeys(accessActivities).map(kA=>{
					let itmAct = accessActivities?.[kA];

					return (
						<ActivityItem itmAct={itmAct} key={kA} idK={kA} updItm={updActivity}/>
					)
				})}
			</div>
			

			<div className="bxupdAct">
				{accessLogistiFunc && ObjectKeys(accessLogistiFunc).map(kA=>{
					let itmAct = accessLogistiFunc?.[kA];

					return (
						<LogisticItem itmAct={itmAct} key={kA} idK={kA} updItm={updActivityLog}/>
					)
				})}
			</div>
			
			



			
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				{diff?.hasChange ?
				<div className="card">
					<button onClick={save}>
						Actualizar
					</button>
				</div>
				:null}
			</div>
		

			
		</div>
	);
};

export default UpdUser;



const ActivityItem =  ({itmAct, idK, updItm}) =>{

	const updK = (v) =>{
		let nne = {...itmAct}
		nne.isActive = v;
		updItm(idK, nne)
		
	}

	
	let isActive = getStore(frmNm)?.["accessActivities"]?.[idK]?.isActive;


	return (
		<div className="_dsplFlx itmAc">
			<span className={`checklabel`}>
				{itmAct.label}
			</span>
			<CheckBoxSlide
				initvalue={isActive}
				keyCode={73}
				updChange={(e)=>updK(e)}
			/>
		</div>
	)
}


const getYearAccBussines = async (businessId) =>{
	let Qry_V = getStore(qryStore())?.get_hrm_years;
	if(Qry_V){
		Qry_V.params = {
			businessId:  businessId || getStore("profileUser")?.businessId,
		}
		const resV = fetchEncryptStream(Qry_V);
		const tdV = await resV;
		
		if (tdV) {
			updStore("YearAccBussinesUsr",tdV);
		}
	}
  }




  const LogisticItem =  ({itmAct, idK, updItm}) =>{

	const updK = (v) =>{
		let nne = {...itmAct}
		nne.isActive = v;
		updItm(idK, nne)
		
	}

	
	let isActive = getStore(frmNm)?.["accessLogistic"]?.[idK]?.isActive;


	return (
		<div className="_dsplFlx itmAc">
			<span className={`checklabel`}>
				{itmAct.label}
			</span>
			<CheckBoxSlide
				initvalue={isActive}
				keyCode={73}
				updChange={(e)=>updK(e)}
			/>
		</div>
	)
}



